// The day's affirmation in Danish, for the country pages in Danish. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Du behøver ikke nå det hele i dag. Den næste lille ting er nok.\", \"Træt er ikke det samme som at fejle. Du er træt, fordi du bliver ved med at være der.\", \"Opvasken kan vente. Du må godt sætte dig i fem minutter.\", \"Morgenmadsprodukter til aftensmad tæller også som at give familien mad.\", \"Hvile er ikke noget, du skal gøre dig fortjent til. Du må hvile dig lige nu.\", \"Nogle dage er sejren, at alle nåede frem til sengetid. Det er en rigtig sejr.\", \"Du gør mere, end nogen ser. Jeg ser det.\", \"Et rodet hjem og elskede børn. Det er en god byttehandel.\", \"På en hård dag ser dit bedste anderledes ud, og det tæller stadig.\", \"Én dyb indånding. Sænk skuldrene. Du klarer det fint.\", \"Det er okay at sænke barren i dag. Du kan hæve den igen en anden dag.\", \"At bede om hjælp er stærkt, ikke svagt.\", \"Du må godt sige nej til én ting mere.\", \"Hvis du følte dig ensom i dag, er du ikke den eneste mor, der har haft det sådan. Vi er mange.\", \"Du fortjener en veninde, der spørger, hvordan du har det, og venter på svaret.\", \"Det er okay at række ud først. De fleste mødre håber, at nogen gør det.\", \"At føle sig overset betyder ikke, at du ikke betyder noget. Du betyder rigtig meget.\", \"Dine følelser giver mening. Du er ikke for meget.\", \"Her behøver du ikke forklare din hårde dag. Vi forstår det.\", \"En besked til en anden mor, hvor der står „også mig“, kan vende en hel dag.\", \"Mad, ble, vugge, forfra. Det er rigtigt arbejde, også når det ligner at sidde stille.\", \"Du og din baby er stadig ved at lære hinanden at kende. Der er ingen hast.\", \"Dagene med en nyfødt er lange. Den her periode varer ikke for evigt.\", \"Hvis alt, du gjorde i dag, var at holde et lille menneske mæt og varm, så har du gjort et stort stykke arbejde.\", \"Du behøver ikke komme hurtigt tilbage til dig selv. Du må bare være, hvor du er.\", \"Uanset hvordan din baby får mad, så passer du på din baby. Det er det, der tæller.\", \"Du kan mangle søvn og være fuld af kærlighed på samme tid.\", \"Hold babyen og lad huset være. Huset er her stadig bagefter.\", \"Et raserianfald i supermarkedet gør dig ikke til en dårlig mor. Det betyder bare, at du har et lille barn.\", \"De små tester grænserne, fordi de føler sig trygge hos dig.\", \"Du holdt roen et minut længere end i går. Det tæller.\", \"Hvis du mistede besindelsen, kan et kram og et „undskyld“ rette op på meget. Og det lærer dem noget godt.\", \"Klistrede hænder, høje stemmer, store følelser. Du opdrager et helt menneske.\", \"Det femte „hvorfor?“ i timen er et lille hoved, der vokser.\", \"Du behøver ikke en perfekt dag for at skabe et glad minde.\", \"En smækket dør er ikke slutningen på historien. Lad lyset være tændt.\", \"Din teenager siger det måske ikke, men det betyder noget, at du altid er der.\", \"At være den rolige i huset er hårdt arbejde. Og du gør det.\", \"Nogle af de bedste samtaler sker i bilen. Bare bliv ved med at køre.\", \"De trækker sig væk for at blive voksne, ikke for at efterlade dig.\", \"Du behøver ikke have alle svarene. At lytte er en stor del af det.\", \"Store børn har stadig brug for dig, bare på stillere måder.\", \"At klare det alene kræver en styrke, de fleste aldrig ser.\", \"Du er mor nok til dit barn. Det har du altid været.\", \"Ét par hænder, hundrede opgaver. Vær mild ved dig selv.\", \"Dine børn lærer ved at se på dig, hvordan et stærkt og kærligt menneske ser ud.\", \"En pause er ikke at forlade din post. Det er sådan, du holder ud.\", \"Ingen fører regnskab. Kærlighed og at være der er det, der betyder noget.\", \"Sorg og kærlighed kommer fra samme sted. At savne nogen viser, hvor meget du har elsket.\", \"Der er ingen rigtig tidsplan for sorg. Tag den tid, du har brug for.\", \"På de svære mærkedage skal du være lige så blid mod dig selv, som du ville være mod en veninde.\", \"Du kan bære på sorg og stadig grine med dine børn. Begge dele er ægte.\", \"Hvis du har mistet en graviditet eller en baby, er det tab ægte, og det er din kærlighed også.\", \"Nogle dage er sorgen stille, og andre dage larmer den. Begge dele er okay.\", \"Få penge betyder ikke lidt kærlighed.\", \"Dine børn vil huske tiden med dig mere end de ting, du købte.\", \"At spørge om hjælp til regningerne er klogt, ikke skamfuldt. Det er det, hjælpen er der for.\", \"En gratis eftermiddag på legepladsen kan være ugens bedste dag.\", \"Du fik pengene til at række en uge mere. Det kræver ægte snilde.\", \"Pengebekymringer er trættende. Du bærer på meget, og du er her stadig.\", \"Du drak et glas vand i dag. Start der.\", \"Alle kom ud ad døren. Skoene passede måske ikke sammen. Stadig en sejr.\", \"Du foretog det opkald, du havde grueligt for. Det var modigt.\", \"Du grinede i dag. Hold fast i det.\", \"Et varmt måltid, en ren T-shirt, en godnathistorie. Små ting bliver til en barndom.\", \"I dag var du venlig mod nogen, også selvom det kun var dig selv.\", \"Fremskridt, ikke perfektion. Du kom videre i dag.\", \"Du blev færdig med én ting på listen. Det er én mere end ingen.\", \"Du er en god mor. At du bekymrer dig om det, viser, hvor meget du holder af dem.\", \"Du er mere end det, du får gjort på en dag.\", \"Dine børn har ikke brug for en perfekt mor. De har brug for dig, og de har dig.\", \"Vær lige så tålmodig med dig selv, som du er med dine børn.\", \"Du må gerne fylde, have ønsker og have dine egne drømme.\", \"En fejl udsletter ikke kærlighed. I morgen er en ny begyndelse.\", \"Du er hele verden for nogen, og du er også dit eget menneske.\", \"Det er okay ikke at nyde hvert eneste minut. Du kan stadig elske dine børn af hele dit hjerte.\", \"Der er ikke én rigtig måde at være mor på. Din måde er også god nok.\", \"Som i træstillingen er det okay at vakle. Du kan finde balancen igen.\", \"Plant fødderne som i bjergstillingen. Du står mere sikkert, end det føles.\", \"Kriger to: stærke ben, åbne arme. Det er dig, når du tager imod den her uge.\", \"Ånd ind på fire, ud på fire. Du er lige her, og du klarer det fint.\", \"Stræk dig bredt som en stjerne. Du må godt fylde.\", \"En bred, dyb squat er svær at holde. Det samme er en lang dag. Og du holder ud.\", \"Du kan læne dig som en halvmåne og stadig stå oprejst.\", \"Du behøver ikke kunne nå tæerne endnu. Hver lille smule udstrækning tæller.\", \"Trekantstilling: én hånd ned, én hånd op. Bliv jordforbundet, og fortsæt med at række ud.\", \"Det er sent. Det, der ikke blev gjort i dag, kan vente til i morgen.\", \"Oppe med babyen på det her tidspunkt? Masser af mødre er vågne sammen med dig lige nu.\", \"Huset er stille. Det her øjeblik er dit. Træk vejret.\", \"Du kom igennem dagen i dag. Det var alt, dagen krævede.\", \"Hvis tankerne kører i nat, så skriv dem ned, og lad dem vente til i morgen.\", \"Hvil øjnene. I morgen må du starte forfra.\", \"Højtider kan være svære såvel som glade. Uanset hvordan den her tid føles for dig, er det okay.\", \"Bordet behøver ikke være perfekt. Det er menneskerne omkring det, der betyder noget.\", \"Hvis du savner nogen ved bordet i år, så vær blid mod dit hjerte.\", \"Tak, mor, for hvert måltid, hver tur og hvert kram.\", \"Du behøver ikke være vært, bage eller smile hele vejen igennem. En enkel højtid er stadig en højtid.\", \"Den bedste gave, dine børn får i år, er tid sammen med dig.\", \"En lille jul er stadig fuld af kærlighed. Det kræver ikke mange penge at gøre den særlig.\", \"Kolde dage, varme kram. Du er det varme sted i dit hjem.\", \"Det er okay at springe noget af julestresset over. Ro er også en gave.\", \"Hvis højtiden er tung for dig i år, er du ikke alene. Tag én dag ad gangen.\"]";D.body.appendChild(e)})();
